CREATE TABLE "ai_content_indexes" ("id" UUID NOT NULL,"content_type" VARCHAR(30) NOT NULL,"source_id" VARCHAR(180) NOT NULL,"title" VARCHAR(255) NOT NULL,"slug" VARCHAR(255),"href" TEXT NOT NULL,"excerpt" TEXT,"body" TEXT NOT NULL,"image" TEXT,"occurred_at" TIMESTAMP(3),"embedding" JSONB NOT NULL,"metadata" JSONB NOT NULL DEFAULT '{}',"content_hash" VARCHAR(64) NOT NULL,"indexed_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "ai_content_indexes_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ai_content_insights" ("id" UUID NOT NULL,"content_type" VARCHAR(30) NOT NULL,"source_id" VARCHAR(180) NOT NULL,"slug" VARCHAR(255),"summary" TEXT NOT NULL,"key_points" JSONB NOT NULL DEFAULT '[]',"related" JSONB NOT NULL DEFAULT '[]',"generated_by" VARCHAR(20) NOT NULL DEFAULT 'local',"content_hash" VARCHAR(64) NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "ai_content_insights_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ai_interactions" ("id" UUID NOT NULL,"actor_type" VARCHAR(20) NOT NULL,"user_id" UUID,"guest_id_hash" VARCHAR(64),"scene" VARCHAR(30) NOT NULL,"action" VARCHAR(30) NOT NULL,"content_type" VARCHAR(30),"source_id" VARCHAR(180),"href" TEXT,"model" VARCHAR(150),"duration_ms" INTEGER,"input_chars" INTEGER,"output_chars" INTEGER,"input_tokens" INTEGER,"output_tokens" INTEGER,"source_count" INTEGER NOT NULL DEFAULT 0,"source_clicked" BOOLEAN NOT NULL DEFAULT false,"continued" BOOLEAN NOT NULL DEFAULT false,"helpful" BOOLEAN,"error_type" VARCHAR(80),"fallback" BOOLEAN NOT NULL DEFAULT false,"metadata" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ai_interactions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ai_author_style_profiles" ("id" UUID NOT NULL,"user_id" UUID NOT NULL,"profile" JSONB NOT NULL DEFAULT '{}',"sample_hash" VARCHAR(64) NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "ai_author_style_profiles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ai_narratives" ("id" UUID NOT NULL,"kind" VARCHAR(30) NOT NULL,"title" VARCHAR(255) NOT NULL,"content" TEXT NOT NULL,"period_start" TIMESTAMP(3),"period_end" TIMESTAMP(3),"filters" JSONB NOT NULL DEFAULT '{}',"node_ids" JSONB NOT NULL DEFAULT '[]',"status" VARCHAR(20) NOT NULL DEFAULT 'draft',"created_by" UUID,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "ai_narratives_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ai_content_indexes_content_type_source_id_key" ON "ai_content_indexes"("content_type","source_id");
CREATE INDEX "ai_content_indexes_content_type_occurred_at_idx" ON "ai_content_indexes"("content_type","occurred_at");
CREATE UNIQUE INDEX "ai_content_insights_content_type_source_id_key" ON "ai_content_insights"("content_type","source_id");
CREATE INDEX "ai_content_insights_content_type_slug_idx" ON "ai_content_insights"("content_type","slug");
CREATE INDEX "ai_interactions_scene_action_created_at_idx" ON "ai_interactions"("scene","action","created_at");
CREATE INDEX "ai_interactions_user_id_created_at_idx" ON "ai_interactions"("user_id","created_at");
CREATE INDEX "ai_interactions_guest_id_hash_created_at_idx" ON "ai_interactions"("guest_id_hash","created_at");
CREATE UNIQUE INDEX "ai_author_style_profiles_user_id_key" ON "ai_author_style_profiles"("user_id");
CREATE INDEX "ai_narratives_kind_period_start_period_end_idx" ON "ai_narratives"("kind","period_start","period_end");
CREATE INDEX "ai_narratives_created_by_created_at_idx" ON "ai_narratives"("created_by","created_at");